def trim_tuple(test_list, K):
    """Write a function to trim each tuple by k in the given tuple list.

    Trim ``K`` elements from both the beginning and the end of each
    tuple in ``test_list`` and return the string representation of
    the resulting list of tuples, as shown in the issue example.
    """
    trimmed = [tuple(tup[K : -K if K else None]) for tup in test_list]
    return str(trimmed)
